<script lang="ts">
  import{enhance}from'$app/forms';import type{SubmitFunction}from'@sveltejs/kit';import{toast}from'svelte-sonner';import type{PageProps}from'./$types';import{Button,Card,ConfirmationDialog,Icon,Input,Select,i18n,tienePermiso}from'$lib';let{data}:PageProps=$props();let open=$state(false),processing=$state(false),form:HTMLFormElement,resolveSubmit:(()=>void)|null=null,rejectSubmit:((e:Error)=>void)|null=null;const types=$derived(data.catalogos?.parametros.filter((p:{codigo_grupo:string})=>p.codigo_grupo==='tipos_documento_mascota')??[]),canCreate=$derived(tienePermiso(data.usuario.permisos,'clinic.pets.update'));const submit:SubmitFunction=()=>{processing=true;return async({result,update})=>{if(result.type==='success'){await update({invalidateAll:true});toast.success(i18n.t('notifications.type.success'),{description:i18n.t('operations.saved')});resolveSubmit?.();}else{const m=result.type==='failure'&&typeof result.data?.operationMessage==='string'?result.data.operationMessage:'operations.saveError';toast.error(i18n.t('notifications.type.error'),{description:i18n.t(m)});rejectSubmit?.(new Error(m));}processing=false;resolveSubmit=null;rejectSubmit=null;};};function confirm(){if(!form.reportValidity())return Promise.reject(new Error('invalid'));return new Promise<void>((r,j)=>{resolveSubmit=r;rejectSubmit=j;form.requestSubmit();});}
</script>
<Card padding="none"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-hairline px-5 py-4"><div><h2 class="text-lg font-semibold text-ink">{i18n.t('pets.tabDocuments')}</h2><p class="mt-1 text-sm text-steel">{i18n.t('pets.documentsHelp')}</p></div>{#if canCreate}<Button onclick={()=>open=true}><Icon name="file-plus-2" size={17}/>{i18n.t('operations.newPetDocument')}</Button>{/if}</div>{#if data.mascota.documentos.length}<div class="divide-y divide-hairline">{#each data.mascota.documentos as document}<article class="flex items-start gap-4 px-5 py-4"><span class="grid size-10 shrink-0 place-items-center rounded-lg bg-primary-soft text-primary"><Icon name="file-text" size={19}/></span><div class="min-w-0 flex-1"><strong class="block text-sm text-ink">{document.titulo}</strong><p class="mt-1 text-xs text-steel">{document.tipo.etiqueta}{document.entidad_emisora ? ` · ${document.entidad_emisora}` : ''}</p>{#if document.observaciones}<p class="mt-2 text-sm text-steel">{document.observaciones}</p>{/if}</div><time class="shrink-0 text-xs text-stone">{new Intl.DateTimeFormat(i18n.locale,{dateStyle:'medium'}).format(new Date(document.realizado_en))}</time></article>{/each}</div>{:else}<div class="grid place-items-center px-5 py-14 text-center"><Icon name="files" size={32} class="text-stone"/><p class="mt-3 text-sm text-steel">{i18n.t('pets.noDocuments')}</p></div>{/if}</Card>
<ConfirmationDialog bind:open size="wide" variant="info" icon="file-plus-2" title={i18n.t('operations.newPetDocument')} description={i18n.t('operations.petDocumentHelp')} confirmLabel={i18n.t('operations.save')} cancelLabel={i18n.t('attentions.cancel')} confirmDisabled={processing} onConfirm={confirm}><form bind:this={form} method="POST" action="?/create" use:enhance={submit} class="grid gap-4 text-left sm:grid-cols-2"><Select name="fid_parametros_tipo" label={i18n.t('operations.documentType')} required><option value="">{i18n.t('forms.select')}</option>{#each types as item}<option value={item.id_parametros}>{item.etiqueta}</option>{/each}</Select><Input name="realizado_en" label={i18n.t('operations.effectiveDate')} type="datetime-local" required/><Input name="titulo" label={i18n.t('operations.title')} required minlength="2" maxlength="180"/><Input name="entidad_emisora" label={i18n.t('operations.issuer')} maxlength="180"/><label class="sm:col-span-2"><span class="mb-1.5 block text-sm font-medium text-charcoal">{i18n.t('operations.observations')}</span><textarea name="observaciones" rows="3" maxlength="500" class="w-full rounded-md border border-hairline-strong bg-canvas px-3.5 py-3 text-sm text-ink"></textarea></label></form></ConfirmationDialog>
